class FinanceInsightMigrationIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;static DataSourceTransactionManager manager;static FinanceAccountingService accounting;static FinanceMigrationService migration;static FinanceInsightService insights;static HttpServer modelServer;static volatile String captured;
 static final UUID TENANT=UUID.fromString("10000000-0000-0000-0000-000000000001");UUID hotel,book,company,author,reviewer;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("93").load().migrate();named=new NamedParameterJdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var audit=new AuditWriter(named,e->{});accounting=new FinanceAccountingService(named,db,access,audit,new ObjectMapper().findAndRegisterModules());migration=new FinanceMigrationService(named,db,access,audit,accounting);modelServer=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);modelServer.createContext("/chat",exchange->{captured=new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);var request=FinanceV2Support.JSON.readTree(captured);var facts=FinanceV2Support.JSON.readTree(request.path("messages").path(1).path("content").asText());String reference=facts.path("facts").path(0).path("id").asText();String body=FinanceV2Support.json(Map.of("model","isolated-test-model","choices",List.of(Map.of("message",Map.of("content",FinanceV2Support.json(Map.of("analysis",List.of(Map.of("text","仅根据已过账金额分析，来源尚未齐备。","citations",List.of(reference))),"recommendations",List.of(Map.of("text","核对缺失来源后再作经营判断","citations",List.of(reference),"uncertainty","缺少业务来源，不能预测完整利润")))))))));byte[] output=body.getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,output.length);exchange.getResponseBody().write(output);exchange.close();});modelServer.start();insights=new FinanceInsightService(named,db,access,audit,accounting,new FinanceAnalysisGateway("http://127.0.0.1:"+modelServer.getAddress().getPort()+"/chat","test-only","test-model",true),manager);}
 @AfterAll static void stop()throws Exception{if(modelServer!=null)modelServer.stop(0);if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();book=UUID.randomUUID();company=UUID.randomUUID();author=account();reviewer=account();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'迁移验收','HOTEL')",hotel,TENANT,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'迁移验收法人',?)",company,TENANT,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,enabled) values(?,?,?,?,?,?,?,?,2,true)",TENANT,hotel,company,author,reviewer,account(),account(),reviewer);as(author,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"迁移验收账套",LocalDate.of(2026,10,1))));account("1002","ASSET","DEBIT",true);account("1122","ASSET","DEBIT",false);account("4001","EQUITY","CREDIT",false);account("6001","REVENUE","CREDIT",false);}
 @Test void actualCsvOpeningPreservesTextAndCommitsOnlyBalancedWholeFile(){UUID batch=UUID.randomUUID();var preview=call(()->migration.preview(batch,book,"OPENING","金蝶已确认余额表","余额.csv",csv("科目,借方,贷方\n1002,12.35,0\n4001,0,12.35\n"),Map.of("accountCode","科目","debit","借方","credit","贷方")));assertThat(preview).containsEntry("errorCount",0).containsEntry("status","PREVIEW");assertThat(jdbc.queryForObject("select count(*) from fa_import_batch where book_id=?",Integer.class,book)).isZero();var committed=call(()->migration.commit(batch,command(preview,0)));assertThat(committed).containsEntry("status","ACTIVE");assertThat(jdbc.queryForObject("select sum(debit) from fa_opening_balance where book_id=?",BigDecimal.class,book)).isEqualByComparingTo("12.35");assertThatThrownBy(()->call(()->migration.transition(batch,command(committed,1),false))).hasMessageContaining("仅未生效");}
 @Test void typedUnclearedSubledgerNeedsReconciliationAndCanCancelUnactivatedRerun(){UUID batch=UUID.randomUUID();var preview=call(()->migration.preview(batch,book,"OPEN_ITEM","金蝶应收明细，编号按文本","未清.csv",csv("编号,科目,名称,方向,业务日,到期日,客户,原额,未清\n00001234567890123456,1122,客户挂账,DEBIT,2026-09-10,2026-10-31,测试客户,100.00,80.00\n"),openItemMapping()));var staged=call(()->migration.commit(batch,command(preview,0)));assertThat(staged).containsEntry("status","STAGED");assertThat(jdbc.queryForObject("select source_key from fm_subledger where batch_id=?",String.class,batch)).isEqualTo("00001234567890123456");assertThatThrownBy(()->call(()->migration.transition(batch,command(staged,1),true))).hasMessageContaining("未核对一致");var cancelled=call(()->migration.transition(batch,command(staged,1),false));assertThat(cancelled).containsEntry("status","CANCELLED");UUID second=UUID.randomUUID();var retry=call(()->migration.preview(second,book,"OPEN_ITEM","修正后重跑","未清.csv",csv("编号,科目,名称,方向,业务日,到期日,客户,原额,未清\n00001234567890123456,1122,客户挂账,DEBIT,2026-09-10,2026-10-31,测试客户,100.00,80.00\n"),openItemMapping()));call(()->migration.commit(second,command(retry,0)));call(()->accounting.imports(new FinanceAccountingModels.Import(UUID.randomUUID(),book,"COMMIT","期初控制表",List.of(new FinanceAccountingModels.Opening("1122",new BigDecimal("80.00"),BigDecimal.ZERO),new FinanceAccountingModels.Opening("4001",BigDecimal.ZERO,new BigDecimal("80.00"))),Map.of("source","确认"))));var active=call(()->migration.transition(second,command(call(()->migration.detail(second)),1),true));assertThat(active).containsEntry("status","ACTIVE");assertThat(((List<?>)call(()->migration.subledger(book,"OPEN_ITEM")).get("items"))).hasSize(1);}
 @Test void invalidRowsNeverPartiallyCommitAndPermissionsCannotCrossHotel(){UUID batch=UUID.randomUUID();var preview=call(()->migration.preview(batch,book,"OPENING","错误余额表","错误.csv",csv("科目,借方,贷方\n1002,1.00,0\nNO-ACCOUNT,0,1.00\n"),Map.of("accountCode","科目","debit","借方","credit","贷方")));assertThat(preview).containsEntry("errorCount",1);assertThatThrownBy(()->call(()->migration.commit(batch,command(preview,0)))).hasMessageContaining("整批未导入");assertThat(jdbc.queryForObject("select count(*) from fa_opening_balance where book_id=?",Integer.class,book)).isZero();as(author,"finance.read");assertThatThrownBy(()->call(()->migration.detail(batch))).isInstanceOf(AccessDeniedException.class);TenantContext.set(new TenantPrincipal(TENANT,author,"TEST",Set.of("TEST"),Set.of("finance.configure"),Set.of(UUID.randomUUID()),Set.of(),false,UUID.randomUUID()));assertThatThrownBy(()->call(()->migration.detail(batch))).isInstanceOf(AccessDeniedException.class);}
 @Test void missingOperatingHistoryIsNullNotZeroAndModelUsesFrozenCitedVersion(){var dashboard=call(()->insights.dashboard("2026-10",hotel));var facts=FinanceV2Support.rows(dashboard.get("facts"));assertThat(facts.stream().filter(r->r.get("id").toString().endsWith(":YOY")).findFirst().orElseThrow().get("value")).isNull();assertThat(facts.stream().filter(r->r.get("id").toString().endsWith(":HEADCOUNT")).findFirst().orElseThrow().get("value")).isNull();var created=insights.generate(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,dashboard.get("reportVersion").toString()));assertThat(created).containsEntry("status","DRAFT");assertThat(captured).doesNotContain("api-key","bank_account","工资明细");UUID report=FinanceV2Support.id(created.get("id"));assertThat(FinanceV2Support.map(created.get("snapshot"))).containsEntry("reportVersion",dashboard.get("reportVersion"));assertThatThrownBy(()->call(()->insights.transition(report,0,false))).hasMessageContaining("不能独立复核");as(reviewer,"finance.read","finance.review","finance.configure");call(()->insights.transition(report,0,false));var published=call(()->insights.transition(report,0,true));assertThat(published).containsEntry("status","PUBLISHED");var exported=call(()->insights.exportAnalysis(report,0,"PUBLISHED","xlsx"));assertThat(exported.reportVersion()).isEqualTo(dashboard.get("reportVersion"));assertThat(exported.content().length).isGreaterThan(1000);assertThatThrownBy(()->call(()->insights.exportAnalysis(report,0,"DRAFT","xlsx"))).hasMessageContaining("状态已变化");call(()->insights.followup(report,new FinanceInsightModels.Recommendation(UUID.randomUUID(),-1,0,"ADOPTED",author,LocalDate.of(2026,11,3),"仅形成核对任务，不付款")));assertThat(jdbc.queryForObject("select count(*) from fi_recommendation where report_id=?",Integer.class,report)).isOne();assertThatThrownBy(()->call(()->insights.edit(report,new FinanceInsightModels.Edit(0,"覆盖已发布",FinanceV2Support.map(created.get("content")))))).hasMessageContaining("不可覆盖");}
 @Test void tenantRlsAndUnconfiguredModelAreFailClosed(){Integer hidden=tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,UUID.randomUUID().toString());return jdbc.queryForObject("select count(*) from fm_batch",Integer.class);});assertThat(hidden).isZero();var unavailable=new FinanceAnalysisGateway("","","",false);assertThat(unavailable.ready()).isFalse();assertThatThrownBy(()->unavailable.analyze(Map.of())).hasMessageContaining("未配置");assertThatThrownBy(()->FinanceInsightService.validateContent(Map.of("analysis",List.of(Map.of("text","凭空断言","citations",List.of("OTHER-HOTEL"))),"recommendations",List.of()),Map.of("facts",List.of(Map.of("id","THIS-HOTEL"))))).hasMessageContaining("有效事实引用");}
 @Test void authorizedQuestionsUseSameScopedSnapshotNeverAcceptSqlAndLeaveImmutableOriginalQuery(){var facts=call(()->insights.dashboard("2026-10",hotel));String version=facts.get("reportVersion").toString();var request=new FinanceInsightModels.Question(UUID.randomUUID(),"2026-10",hotel,version,"REVENUE","营业收入来源未齐，现阶段能够判断什么？",true);var result=insights.ask(request);assertThat(result).containsEntry("status","COMPLETE").containsEntry("sourceReportVersion",version).containsEntry("question",request.question());assertThat(captured).contains("READ_ONLY_FINANCIAL_QUESTION_NO_SQL_NO_ACTIONS_NO_SCOPE_EXPANSION").doesNotContain("bank_account","个人工资");assertThat(FinanceV2Support.rows(result.get("facts"))).allSatisfy(f->assertThat(f.get("id").toString()).endsWith(":revenue"));assertThat(insights.ask(request)).containsEntry("id",request.requestId());assertThatThrownBy(()->insights.ask(new FinanceInsightModels.Question(UUID.randomUUID(),"2026-10",hotel,version,"REVENUE","select * from finance_claim",true))).hasMessageContaining("不接受SQL");assertThatThrownBy(()->insights.ask(new FinanceInsightModels.Question(UUID.randomUUID(),"2026-10",hotel,version,"CASH","帮我立即付款100元",true))).hasMessageContaining("不能触发");assertThatThrownBy(()->jdbc.update("update fi_question set question='覆盖原问题' where id=?",request.requestId())).hasMessageContaining("immutable");TenantContext.set(new TenantPrincipal(TENANT,author,"TEST",Set.of("TEST"),Set.of("finance.read"),Set.of(UUID.randomUUID()),Set.of(),false,UUID.randomUUID()));assertThatThrownBy(()->call(()->insights.answer(request.requestId()))).isInstanceOf(AccessDeniedException.class);}
 @Test void frozenExportsRemainSameVersionAndMetricRevisionsCompareWithoutFakingHistoricalData()throws Exception{var first=call(()->insights.dashboard("2026-10",hotel));var frozen=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,first.get("reportVersion").toString())));UUID snapshot=FinanceV2Support.id(frozen.get("snapshotId"));call(()->insights.saveMetric(new FinanceInsightModels.Metric(UUID.randomUUID(),hotel,"2026-10","HEADCOUNT","",new BigDecimal("8"),"已确认10月平均在岗人数",-1)));var latest=call(()->insights.dashboard("2026-10",hotel));assertThat(latest.get("reportVersion")).isNotEqualTo(first.get("reportVersion"));assertThatThrownBy(()->call(()->insights.export("2026-10",hotel,null,first.get("reportVersion").toString(),"xlsx"))).hasMessageContaining("版本已变化");var exported=call(()->insights.export(null,null,snapshot,first.get("reportVersion").toString(),"xlsx"));try(var workbook=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(exported.content()))){assertThat(workbook.getSheet("经营事实与完整性")).isNotNull();assertThat(workbook.getSheet("口径与冻结版本").getRow(0).getCell(1).getStringCellValue()).isEqualTo(first.get("reportVersion"));}var next=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,latest.get("reportVersion").toString())));assertThat((List<?>)call(()->insights.compare(snapshot,FinanceV2Support.id(next.get("snapshotId")))).get("changes")).isNotEmpty();assertThat(call(()->insights.snapshot(snapshot))).containsEntry("reportVersion",first.get("reportVersion"));}
 @Test void assetMigrationReconcilesGrossAndAccumulatedAccountsAndNeverCreatesPhysicalStock(){account("1601","ASSET","DEBIT",false);account("1602","ASSET","CREDIT",false);UUID physical=UUID.randomUUID();jdbc.update("insert into store_fixed_asset(id,tenant_id,hotel_org_unit_id,asset_code,name,category,original_value) values(?,?,?,?,?,'设备',100.00)",physical,TENANT,hotel,"PHYSICAL-001","既有实物");String source="编号,科目,累折科目,实物ID,投用日,原寿命,名称,方向,业务日,原值,净值,累折,残值,剩余月\n001,1601,1602,"+physical+",2025-10-01,24,设备,DEBIT,2025-10-01,100.00,80.00,20.00,5.00,12\n";var mapping=new LinkedHashMap<String,String>();mapping.put("sourceKey","编号");mapping.put("accountCode","科目");mapping.put("accumulatedAccountCode","累折科目");mapping.put("physicalAssetId","实物ID");mapping.put("inServiceDate","投用日");mapping.put("originalUsefulMonths","原寿命");mapping.put("name","名称");mapping.put("direction","方向");mapping.put("businessDate","业务日");mapping.put("originalAmount","原值");mapping.put("remainingAmount","净值");mapping.put("accumulatedAmount","累折");mapping.put("residualAmount","残值");mapping.put("remainingMonths","剩余月");UUID batch=UUID.randomUUID();var preview=call(()->migration.preview(batch,book,"ASSET","金蝶原值与折旧卡片","资产.csv",csv(source),mapping));assertThat(preview).containsEntry("errorCount",0);var staged=call(()->migration.commit(batch,command(preview,0)));call(()->accounting.imports(new FinanceAccountingModels.Import(UUID.randomUUID(),book,"COMMIT","期初原值与累折",List.of(new FinanceAccountingModels.Opening("1601",new BigDecimal("100.00"),BigDecimal.ZERO),new FinanceAccountingModels.Opening("1602",BigDecimal.ZERO,new BigDecimal("20.00")),new FinanceAccountingModels.Opening("4001",BigDecimal.ZERO,new BigDecimal("80.00"))),Map.of("source","核对通过"))));call(()->migration.transition(batch,command(staged,1),true));assertThat(jdbc.queryForObject("select remaining_amount from fm_subledger where batch_id=?",BigDecimal.class,batch)).isEqualByComparingTo("80.00");assertThat(jdbc.queryForObject("select count(*) from store_fixed_asset where hotel_org_unit_id=?",Integer.class,hotel)).isOne();assertThatThrownBy(()->jdbc.update("update fm_subledger set remaining_amount=0 where batch_id=?",batch)).hasMessageContaining("immutable");}
 @Test void pmsAgingKeepsPriorRevisionReceiptsAndWalletConsumptionAtSelectedMonthEnd(){UUID oldBatch=UUID.randomUUID(),batch=UUID.randomUUID(),old=UUID.randomUUID(),current=UUID.randomUUID(),wallet=UUID.randomUUID();
  jdbc.update("insert into fb_revenue_batch(id,tenant_id,hotel_id,company_id,source,channel,business_date,night_audit_date,revision,expected_count,control_total,source_reference,status,source_hash,created_by,reviewer_id) values(?,?,?,?,'PMS','PMS-DIRECT','2026-10-01','2026-10-02',1,1,100,'首版实际来源','SUPERSEDED',?,?,?)",oldBatch,TENANT,hotel,company,"a".repeat(64),author,reviewer);
  jdbc.update("insert into fb_revenue_batch(id,tenant_id,hotel_id,company_id,source,channel,business_date,night_audit_date,revision,expected_count,control_total,source_reference,status,source_hash,created_by,reviewer_id) values(?,?,?,?,'PMS','PMS-DIRECT','2026-10-01','2026-10-02',2,2,430,'重结完整来源','CONFIRMED',?,?,?)",batch,TENANT,hotel,company,"b".repeat(64),author,reviewer);
  jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,active) values(?,?,?,?,?,'ROOM-001','AR','测试客户','PMS-DIRECT','2026-10-15',100,100,0,0,0,false)",old,TENANT,oldBatch,hotel,company);
  jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,active,previous_id) values(?,?,?,?,?,'ROOM-001','AR','测试客户','PMS-DIRECT','2026-10-15',130,130,0,10,5,true,?)",current,TENANT,batch,hotel,company,old);
  jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,active) values(?,?,?,?,?,'WALLET-001','STORED_VALUE','测试客户','PMS-DIRECT','2026-10-15',300,300,0,0,0,true)",wallet,TENANT,batch,hotel,company);
  agingMovement(old,null,"RECEIPT","30.00","2026-10-12");agingMovement(current,null,"RECEIPT","40.00","2026-11-02");agingMovement(wallet,null,"RECEIPT","100.00","2026-10-05");agingMovement(wallet,old,"REDEEM","20.00","2026-10-20");agingMovement(wallet,current,"REDEEM","25.00","2026-11-03");
  var october=FinanceV2Support.rows(call(()->insights.dashboard("2026-10",hotel)).get("aging"));var item=october.stream().filter(r->current.toString().equals(r.get("id").toString())).findFirst().orElseThrow();assertThat(new BigDecimal(item.get("remainingAmount").toString())).isEqualByComparingTo("65.00");assertThat(october).noneMatch(r->wallet.toString().equals(r.get("id").toString()));
  var november=FinanceV2Support.rows(call(()->insights.dashboard("2026-11",hotel)).get("aging"));var after=november.stream().filter(r->current.toString().equals(r.get("id").toString())).findFirst().orElseThrow();assertThat(new BigDecimal(after.get("remainingAmount").toString())).isEqualByComparingTo("0.00");
 }
 private void agingMovement(UUID entry,UUID related,String kind,String amount,String day){jdbc.update("insert into fb_revenue_movement(id,tenant_id,entry_id,related_entry_id,kind,amount,occurred_on,bank_reference,note,created_by) values(?,?,?,?,?,cast(? as numeric),cast(? as date),'测试银行流水','按实际资金/消费时点',?)",UUID.randomUUID(),TENANT,entry,related,kind,amount,day,author);}
 private Map<String,String> openItemMapping(){return Map.of("sourceKey","编号","accountCode","科目","name","名称","direction","方向","businessDate","业务日","dueDate","到期日","partyName","客户","originalAmount","原额","remainingAmount","未清");}
 private FinanceMigrationModels.Command command(Map<String,Object> batch,int version){return new FinanceMigrationModels.Command(version,batch.get("fileSha256").toString(),"独立核对真实导出来源与期初");}
 private static byte[] csv(String value){return value.getBytes(StandardCharsets.UTF_8);}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'隔离测试')",id,TENANT,id.toString());return id;}
 private void account(String code,String category,String normal,boolean cash){call(()->accounting.saveAccount(new FinanceAccountingModels.Account(book,code,code,category,normal,code,cash,true,-1)));}
 private void as(UUID actor,String...permissions){TenantContext.set(new TenantPrincipal(TENANT,actor,"TEST",Set.of("TEST"),Set.of(permissions),Set.of(hotel),Set.of(),false,UUID.randomUUID()));}
 private static <T>T call(Supplier<T> action){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return action.get();});}
}
